package main

// OTA self-update (v0.6).
//
// Flow:
//   1. The daemon checks the latest Release of the GitHub repo. The
//      repo is public since v0.7, so no token is needed; a stored
//      read-only token (Data/update-token.txt) is only used if the
//      repo ever goes private again -- and if a stale token makes
//      GitHub answer 401, requests are retried anonymously.
//   2. It downloads the small update.json manifest attached to the
//      Release (version / zip size / SHA-256, generated by CI), then
//      the package zip, verifying size + SHA-256 before trusting it.
//   3. The extracted MJ-System.exe is staged in Data/update/. On apply,
//      the staged (new) binary is spawned with -apply-update: it asks
//      the old daemon to shut down, renames the old EXE to
//      MJ-System.exe.old (renaming a running EXE is allowed on
//      Windows), copies itself into place, launches it, and waits for
//      the new daemon to answer with the new version. If that never
//      happens it rolls back to .old. The new daemon deletes .old
//      once it is up.
//
// Nothing here ever touches the system proxy or anything outside the
// program folder and Data/.

import (
	"archive/zip"
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

// AppVersion is the single source of truth for the running version.
// The CI workflow must publish the Release with the matching tag
// (v + AppVersion) and update.json.
const AppVersion = "0.57"

const updateRepo = "xumingjie14/MJ-Terminal"
const updateZipName = "MJ-System-64bit.zip"
const updateManifestName = "update.json"

type updateManifest struct {
	Version string `json:"version"`
	File    string `json:"file"`
	Size    int64  `json:"size"`
	SHA256  string `json:"sha256"`
}

type updateStatus struct {
	mu          sync.Mutex
	Phase       string // idle|checking|uptodate|available|downloading|ready|error
	Latest      string
	Size        int64
	Progress    int64
	Message     string
	zipAssetURL string // api.github.com URL of the zip asset
	sha256      string
}

var upd = updateStatus{Phase: "idle"}

func updateDir() string {
	d := filepath.Join(dataDir(), "update")
	_ = os.MkdirAll(d, 0o755)
	return d
}

func updateTokenPath() string { return filepath.Join(dataDir(), "update-token.txt") }

func readUpdateToken() string {
	b, status, err := dsLoad("update-token")
	if err != nil || status == dsMissing {
		return ""
	}
	return strings.TrimSpace(string(b))
}

func stagedExePath() string { return filepath.Join(updateDir(), "MJ-System.exe") }

func (u *updateStatus) set(phase, msg string) {
	u.mu.Lock()
	u.Phase, u.Message = phase, msg
	u.mu.Unlock()
	// Mirror terminal update states into the diagnostics hub (v0.22):
	// every check/download failure and every success lands there.
	// Messages never contain the update token itself.
	switch phase {
	case "error":
		logf("update", "error", "软件更新：%s", msg)
	case "available", "uptodate", "ready":
		logf("update", "info", "软件更新：%s", msg)
	}
}

func (u *updateStatus) snapshot() map[string]any {
	u.mu.Lock()
	defer u.mu.Unlock()
	return map[string]any{
		"current":  AppVersion,
		"token":    readUpdateToken() != "",
		"phase":    u.Phase,
		"latest":   u.Latest,
		"size":     u.Size,
		"progress": u.Progress,
		"message":  u.Message,
	}
}

// ---------- version compare ----------

func parseVersion(s string) []int {
	s = strings.TrimPrefix(strings.TrimSpace(s), "v")
	parts := strings.Split(s, ".")
	out := make([]int, len(parts))
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil {
			return out[:i]
		}
		out[i] = n
	}
	return out
}

// compareVersions returns -1/0/1 for a <==> b.
func compareVersions(a, b string) int {
	pa, pb := parseVersion(a), parseVersion(b)
	for i := 0; i < len(pa) || i < len(pb); i++ {
		var x, y int
		if i < len(pa) {
			x = pa[i]
		}
		if i < len(pb) {
			y = pb[i]
		}
		if x != y {
			if x < y {
				return -1
			}
			return 1
		}
	}
	return 0
}

// ---------- GitHub helpers ----------

func ghRequest(ctx context.Context, url, accept string, useToken bool) (*http.Response, error) {
	return ghRequestH(ctx, url, accept, useToken, nil)
}

func ghRequestH(ctx context.Context, url, accept string, useToken bool, headers map[string]string) (*http.Response, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", accept)
	req.Header.Set("X-GitHub-Api-Version", "2022-11-28")
	req.Header.Set("User-Agent", "MJ-Terminal-Updater/"+AppVersion)
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	if useToken {
		if tok := readUpdateToken(); tok != "" {
			req.Header.Set("Authorization", "Bearer "+tok)
		}
	}
	resp, err := dlClient().Do(req)
	if err != nil && proxyActive() {
		resp, err = http.DefaultClient.Do(req)
	}
	return resp, err
}

// ghSend issues a GET, and if a stored token makes GitHub answer 401
// (stale or wrong token), it retries once anonymously: the repo is
// public, so a bad token must never be able to block updates.
func ghSend(ctx context.Context, url, accept string) (*http.Response, error) {
	return ghSendH(ctx, url, accept, nil)
}

func ghSendH(ctx context.Context, url, accept string, headers map[string]string) (*http.Response, error) {
	withToken := readUpdateToken() != ""
	resp, err := ghRequestH(ctx, url, accept, withToken, headers)
	if err != nil || !withToken || resp.StatusCode != http.StatusUnauthorized {
		return resp, err
	}
	_ = resp.Body.Close()
	return ghRequestH(ctx, url, accept, false, headers)
}

func ghGetJSON(ctx context.Context, url string, limit int64) ([]byte, int, error) {
	resp, err := ghSend(ctx, url, "application/vnd.github+json")
	if err != nil {
		return nil, 0, err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(io.LimitReader(resp.Body, limit))
	return b, resp.StatusCode, err
}

func ghGetAsset(ctx context.Context, url string, limit int64) ([]byte, int, error) {
	resp, err := ghSend(ctx, url, "application/octet-stream")
	if err != nil {
		return nil, 0, err
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(io.LimitReader(resp.Body, limit))
	return b, resp.StatusCode, err
}

// ---------- check ----------

// checkUpdate talks to GitHub and refreshes upd state. Blocking; the
// HTTP handler runs it inline (bounded by ctx timeouts).
func checkUpdate() {
	upd.set("checking", "正在检查更新…")
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	body, code, err := ghGetJSON(ctx, "https://api.github.com/repos/"+updateRepo+"/releases/latest", 2*1024*1024)
	if err != nil {
		upd.set("error", "检查失败：连不上 GitHub（"+err.Error()+"）")
		return
	}
	if code != http.StatusOK {
		upd.set("error", fmt.Sprintf("检查失败：GitHub 返回 %d（多半是网络问题；若仓库改回私有，则需要有效的更新令牌）", code))
		return
	}
	var rel struct {
		TagName string `json:"tag_name"`
		Assets  []struct {
			Name string `json:"name"`
			URL  string `json:"url"`
		} `json:"assets"`
	}
	if err := json.Unmarshal(body, &rel); err != nil {
		upd.set("error", "检查失败：Release 信息解析不了")
		return
	}
	var manifestURL, zipURL string
	for _, a := range rel.Assets {
		switch a.Name {
		case updateManifestName:
			manifestURL = a.URL
		case updateZipName:
			zipURL = a.URL
		}
	}
	if manifestURL == "" || zipURL == "" {
		upd.set("error", "最新 Release 里缺 update.json 或安装包，无法更新")
		return
	}
	mb, code, err := ghGetAsset(ctx, manifestURL, 64*1024)
	if err != nil || code != http.StatusOK {
		upd.set("error", "检查失败：读不到更新清单 update.json")
		return
	}
	mb = bytes.TrimPrefix(mb, []byte{0xEF, 0xBB, 0xBF}) // tolerate a BOM
	var man updateManifest
	if err := json.Unmarshal(mb, &man); err != nil || man.Version == "" {
		upd.set("error", "检查失败：更新清单内容不对")
		return
	}
	upd.mu.Lock()
	upd.Latest, upd.Size, upd.sha256, upd.zipAssetURL = man.Version, man.Size, man.SHA256, zipURL
	upd.mu.Unlock()
	if compareVersions(man.Version, AppVersion) > 0 {
		upd.set("available", fmt.Sprintf("发现新版本 v%s（当前 v%s），大小 %.1f MB", man.Version, AppVersion, float64(man.Size)/1024/1024))
		// v0.47 hook (notify): one event per detected version, at
		// the detection moment only (postNotifyOnce persists its
		// key). The persistent "update available" presence in
		// Notification Center is the status item, assembled from
		// this same phase -- the event exists to raise the banner.
		postNotifyOnce("update-available:"+man.Version, notifySrcUpdate, "available",
			"发现新版本 v"+man.Version, fmt.Sprintf("新版本 v%s 已可下载（当前 v%s）", man.Version, AppVersion), "setpage:update")
	} else {
		upd.set("uptodate", "已经是最新版本 v"+AppVersion)
	}
}

// ---------- download ----------

// renameRetrySleep is indirected so tests can compress the
// backoff schedule.
var renameRetrySleep = time.Sleep

// renameWithRetry runs renameFn until it succeeds, with a
// growing backoff (~50 s across 12 attempts). The v0.47 field
// failure being fixed here: the 58.8 MB package downloaded
// completely, then the final one-shot rename of pkg.zip.part
// died with "The process cannot access the file because it is
// being used by another process" -- four attempts in one evening,
// all dead at the same step. A transient lock (the prime suspect
// is the host antivirus scanning the fresh ~62 MB zip; an
// unclosed handle of our own is the other, audited below) needs
// a window to let go, not a single try.
func renameWithRetry(renameFn func() error, logAttempt func(attempt int, err error)) error {
	delays := []time.Duration{
		0, time.Second, 1500 * time.Millisecond, 2 * time.Second,
		2500 * time.Millisecond, 3 * time.Second, 4 * time.Second,
		5 * time.Second, 6 * time.Second, 7 * time.Second,
		8 * time.Second, 10 * time.Second,
	}
	var err error
	for i, d := range delays {
		if d > 0 {
			renameRetrySleep(d)
		}
		if err = renameFn(); err == nil {
			return nil
		}
		if logAttempt != nil {
			logAttempt(i+1, err)
		}
	}
	return err
}

// finalizePartFile moves a completed .part download to its
// final name: backoff rename first; if the lock still will not
// let go, a copy with a fresh handle (size-verified, then the
// part is removed).
func finalizePartFile(part, dest string) error {
	err := renameWithRetry(func() error { return os.Rename(part, dest) }, func(attempt int, err error) {
		logf("update", "warn", "更新包改名被占用（第 %d 次）：%v", attempt, err)
	})
	if err == nil {
		return nil
	}
	logf("update", "warn", "更新包改名多次仍失败，改走复制兜底：%v", err)
	in, ierr := os.Open(part)
	if ierr != nil {
		return ierr
	}
	defer in.Close()
	st, serr := in.Stat()
	if serr != nil {
		return serr
	}
	out, oerr := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o644)
	if oerr != nil {
		return oerr
	}
	_, cerr := io.Copy(out, in)
	if cerr == nil {
		cerr = out.Sync()
	}
	clerr := out.Close()
	if cerr != nil {
		return cerr
	}
	if clerr != nil {
		return clerr
	}
	dst, derr := os.Stat(dest)
	if derr != nil {
		return derr
	}
	if dst.Size() != st.Size() {
		return fmt.Errorf("复制出的更新包大小对不上（%d / %d 字节）", dst.Size(), st.Size())
	}
	_ = os.Remove(part)
	return nil
}

// partFileStatus inspects an existing .part file against the
// manifest. complete=true means the file IS the package (size
// matches AND, when the manifest carries one, SHA-256 matches)
// and the download can be skipped outright. Otherwise
// resumeFrom is the byte count usable as a Range prefix -- size
// only; the whole-file SHA-256 verdict after the transfer is
// the arbiter, so a lying prefix costs a failed check, never a
// bad install.
func partFileStatus(part string, wantSize int64, wantSHA string) (complete bool, resumeFrom int64) {
	st, err := os.Stat(part)
	if err != nil || wantSize <= 0 {
		return false, 0
	}
	switch {
	case st.Size() == wantSize:
		if wantSHA == "" {
			return true, st.Size()
		}
		if sum, herr := vaultHashFile(part); herr == nil && strings.EqualFold(sum, wantSHA) {
			return true, st.Size()
		}
		return false, 0 // full size, wrong content: start over
	case st.Size() < wantSize:
		return false, st.Size()
	default:
		return false, 0 // oversized: corrupt, start over
	}
}

// fetchUpdateZip transfers the release zip into part, resuming
// from resumeFrom bytes when >0 (a server answering 200 instead
// of 206 restarts the transfer cleanly). Size + SHA-256 are
// verified over the WHOLE assembled file before it returns
// true; every failure sets the upd error state itself.
//
// Handle discipline (audited for v0.48): the .part handle is
// closed EXPLICITLY at the end of the write loop -- before the
// verdict and long before any rename -- never carried across
// them by a defer.
func fetchUpdateZip(ctx context.Context, zipURL, part string, resumeFrom, wantSize int64, wantSHA string) bool {
	var resp *http.Response
	var err error
	for attempt := 0; attempt < 2; attempt++ {
		var headers map[string]string
		if resumeFrom > 0 {
			headers = map[string]string{"Range": fmt.Sprintf("bytes=%d-", resumeFrom)}
		}
		resp, err = ghSendH(ctx, zipURL, "application/octet-stream", headers)
		if err != nil {
			upd.set("error", "下载失败："+err.Error())
			return false
		}
		if resumeFrom > 0 && resp.StatusCode == http.StatusPartialContent {
			var start int64 = -1
			if _, serr := fmt.Sscanf(resp.Header.Get("Content-Range"), "bytes %d-", &start); serr == nil && start == resumeFrom {
				break
			}
			_ = resp.Body.Close()
			resumeFrom = 0 // a range reply that starts elsewhere: restart plainly
			continue
		}
		if resp.StatusCode == http.StatusOK {
			resumeFrom = 0 // Range ignored (or never sent): the full body follows
			break
		}
		_ = resp.Body.Close()
		upd.set("error", fmt.Sprintf("下载失败：GitHub 返回 %d", resp.StatusCode))
		return false
	}
	defer resp.Body.Close()

	h := sha256.New()
	var f *os.File
	if resumeFrom > 0 {
		// Hash the held prefix first, so the final verdict
		// covers the whole file.
		pf, perr := os.Open(part)
		if perr != nil {
			upd.set("error", "下载失败："+perr.Error())
			return false
		}
		_, herr := io.Copy(h, pf)
		_ = pf.Close()
		if herr != nil {
			upd.set("error", "下载失败："+herr.Error())
			return false
		}
		f, err = os.OpenFile(part, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	} else {
		f, err = os.Create(part)
	}
	if err != nil {
		upd.set("error", "下载失败："+err.Error())
		return false
	}
	written := resumeFrom
	upd.mu.Lock()
	upd.Progress = written
	upd.mu.Unlock()
	buf := make([]byte, 256*1024)
	for {
		n, rerr := resp.Body.Read(buf)
		if n > 0 {
			if _, werr := f.Write(buf[:n]); werr != nil {
				_ = f.Close()
				upd.set("error", "下载失败（写入）："+werr.Error())
				return false
			}
			_, _ = h.Write(buf[:n])
			written += int64(n)
			upd.mu.Lock()
			upd.Progress = written
			upd.mu.Unlock()
		}
		if rerr == io.EOF {
			break
		}
		if rerr != nil {
			_ = f.Close()
			upd.set("error", "下载中断："+rerr.Error())
			return false
		}
	}
	if cerr := f.Close(); cerr != nil {
		upd.set("error", "下载失败（关闭文件）："+cerr.Error())
		return false
	}
	if wantSize > 0 && written != wantSize {
		upd.set("error", fmt.Sprintf("下载不完整：大小对不上（%d / %d 字节）", written, wantSize))
		return false
	}
	gotSHA := hex.EncodeToString(h.Sum(nil))
	if wantSHA != "" && !strings.EqualFold(gotSHA, wantSHA) {
		upd.set("error", "校验失败：SHA-256 对不上，已放弃这次更新")
		return false
	}
	return true
}

// downloadUpdate fetches the zip asset (or reuses / resumes a
// previous attempt's .part), verifies size + SHA-256 against
// the manifest, then stages MJ-System.exe in Data/update/.
func downloadUpdate() {
	upd.mu.Lock()
	zipURL, wantSize, wantSHA := upd.zipAssetURL, upd.Size, upd.sha256
	upd.Progress = 0
	upd.mu.Unlock()
	if zipURL == "" {
		upd.set("error", "还没有检查到可下载的更新")
		return
	}
	ensureCoreForDownload()
	part := filepath.Join(updateDir(), "pkg.zip.part")
	zipPath := filepath.Join(updateDir(), "pkg.zip")
	complete, resumeFrom := partFileStatus(part, wantSize, wantSHA)
	if complete {
		logf("update", "info", "软件更新：上次已下载完整的更新包（大小与 SHA-256 均与清单一致），跳过下载")
		upd.mu.Lock()
		upd.Progress = wantSize
		upd.mu.Unlock()
	} else {
		if resumeFrom == 0 {
			_ = os.Remove(part) // wrong-size/corrupt leftover: start clean
		} else {
			logf("update", "info", "软件更新：断点续传（已有 %s / %s）", fmtBytes(resumeFrom), fmtBytes(wantSize))
		}
		upd.set("downloading", "正在下载更新包（"+downloadRoute()+"）…")
		ctx, cancel := context.WithTimeout(context.Background(), 15*time.Minute)
		ok := fetchUpdateZip(ctx, zipURL, part, resumeFrom, wantSize, wantSHA)
		cancel()
		if !ok {
			return
		}
	}
	_ = os.Remove(zipPath)
	if err := finalizePartFile(part, zipPath); err != nil {
		upd.set("error", "下载失败："+err.Error())
		return
	}
	// Extract the single EXE from the package.
	zr, err := zip.OpenReader(zipPath)
	if err != nil {
		upd.set("error", "安装包打不开："+err.Error())
		return
	}
	defer zr.Close()
	var staged bool
	for _, zf := range zr.File {
		if filepath.Base(zf.Name) != "MJ-System.exe" {
			continue
		}
		rc, err := zf.Open()
		if err != nil {
			break
		}
		data, err := io.ReadAll(rc)
		_ = rc.Close()
		if err != nil || len(data) < 10*1024*1024 || !bytes.HasPrefix(data, []byte("MZ")) {
			upd.set("error", "安装包里的程序文件不对，已放弃")
			return
		}
		tmp := stagedExePath() + ".tmp"
		if err := os.WriteFile(tmp, data, 0o755); err == nil {
			_ = os.Remove(stagedExePath())
			if err := renameWithRetry(func() error { return os.Rename(tmp, stagedExePath()) }, nil); err == nil {
				staged = true
			}
		}
		break
	}
	if !staged {
		upd.set("error", "安装包里没找到 MJ-System.exe")
		return
	}
	upd.set("ready", "新版本已下载并验过，点「重启并更新」完成更新（节点会断开几秒，自动重连）")
}

// ---------- HTTP handlers ----------

func updateStatusHandler(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, upd.snapshot())
}

func updateTokenHandler(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Token string `json:"token"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeJSON(w, map[string]any{"error": "bad request"})
		return
	}
	tok := strings.TrimSpace(body.Token)
	if tok == "" {
		_ = os.Remove(updateTokenPath())
		writeJSON(w, map[string]any{"ok": true, "token": false})
		return
	}
	if err := dsSave("update-token", []byte(tok)); err != nil {
		writeJSON(w, map[string]any{"error": err.Error()})
		return
	}
	writeJSON(w, map[string]any{"ok": true, "token": true})
}

func updateCheckHandler(w http.ResponseWriter, r *http.Request) {
	checkUpdate()
	writeJSON(w, upd.snapshot())
}

func updateDownloadHandler(w http.ResponseWriter, r *http.Request) {
	upd.mu.Lock()
	phase := upd.Phase
	upd.mu.Unlock()
	if phase == "downloading" {
		writeJSON(w, upd.snapshot())
		return
	}
	if phase != "available" {
		checkUpdate()
	}
	upd.mu.Lock()
	phase = upd.Phase
	upd.mu.Unlock()
	if phase != "available" {
		writeJSON(w, upd.snapshot())
		return
	}
	go downloadUpdate()
	writeJSON(w, upd.snapshot())
}

// updateApplyHandler hands over to the staged new binary, which does
// the file swap (see runApplyUpdate), then this daemon exits.
func updateApplyHandler(w http.ResponseWriter, r *http.Request) {
	upd.mu.Lock()
	phase := upd.Phase
	latest := upd.Latest
	upd.mu.Unlock()
	if phase != "ready" {
		writeJSON(w, map[string]any{"error": "更新包还没准备好，先检查并下载更新"})
		return
	}
	self, err := os.Executable()
	if err != nil {
		writeJSON(w, map[string]any{"error": err.Error()})
		return
	}
	updater := exec.Command(stagedExePath(), "-apply-update", "-update-target", self)
	updater.Dir = updateDir()
	if err := updater.Start(); err != nil {
		logf("update", "error", "启动更新程序失败：%v", err)
		writeJSON(w, map[string]any{"error": "启动更新程序失败：" + err.Error()})
		return
	}
	logf("update", "info", "开始应用更新（v%s → v%s），守护进程交接退出", AppVersion, latest)
	writeJSON(w, map[string]any{"ok": true, "message": "正在更新，桌面会自动重开"})
	// The updater also asks us to shut down over HTTP; exiting here as
	// well makes the handover robust if that call races. Either way
	// it is a HANDOVER exit: no app closing, no vault sealing.
	go func() {
		time.Sleep(800 * time.Millisecond)
		requestDaemonExit(exitHandover)
	}()
}

// ---------- updater mode (runs inside the NEW binary) ----------

func applyLog(format string, args ...any) {
	line := time.Now().Format("15:04:05 ") + fmt.Sprintf(format, args...) + "\n"
	f, err := os.OpenFile(filepath.Join(updateDir(), "apply.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err == nil {
		_, _ = f.WriteString(line)
		_ = f.Close()
	}
}

// daemonVersionAt returns the version reported by the daemon on a
// port, "" when nothing MJ-like answers.
func daemonVersionAt(port int) string {
	client := &http.Client{Timeout: 600 * time.Millisecond}
	resp, err := client.Get(fmt.Sprintf("http://127.0.0.1:%d/api/system", port))
	if err != nil {
		return ""
	}
	defer resp.Body.Close()
	var v struct {
		App     string `json:"app"`
		Version string `json:"version"`
	}
	if json.NewDecoder(resp.Body).Decode(&v) != nil || v.App != "MJ-Terminal" {
		return ""
	}
	return v.Version
}

func anyDaemonUp() bool {
	for p := daemonBasePort; p < daemonBasePort+daemonPortSpan; p++ {
		if daemonVersionAt(p) != "" {
			return true
		}
	}
	return false
}

func newDaemonHealthy() bool {
	for p := daemonBasePort; p < daemonBasePort+daemonPortSpan; p++ {
		if daemonVersionAt(p) == AppVersion {
			return true
		}
	}
	return false
}

// runApplyUpdate executes inside the staged NEW binary: shut the old
// daemon down, swap the EXE files, launch the new one, verify, and
// roll back to .old if the new daemon never comes up healthy.
func runApplyUpdate(target string) {
	self, err := os.Executable()
	if err != nil || target == "" {
		return
	}
	applyLog("apply-update: self=%s target=%s version=%s", self, target, AppVersion)
	// 1) Ask the old daemon to shut down (stops core + daemon).
	//    The handover marker keeps the old daemon from treating
	//    this as a user exit (v0.48: no app closing, no sealing).
	if url := findDaemon(); url != "" {
		client := &http.Client{Timeout: 2 * time.Second}
		req, _ := http.NewRequest(http.MethodPost, url+"api/shutdown?handover=1", nil)
		if req != nil {
			resp, err := client.Do(req)
			if err == nil {
				_ = resp.Body.Close()
			}
		}
	}
	// 2) Wait for the old daemon to disappear (max ~20s).
	for i := 0; i < 40 && anyDaemonUp(); i++ {
		time.Sleep(500 * time.Millisecond)
	}
	// 3) Rename old -> .old (allowed even while it is still exiting),
	//    then copy ourselves into place.
	old := target + ".old"
	_ = os.Remove(old)
	renamed := false
	for i := 0; i < 40; i++ {
		if err := os.Rename(target, old); err == nil {
			renamed = true
			break
		}
		time.Sleep(500 * time.Millisecond)
	}
	if !renamed {
		applyLog("FAILED: cannot rename target")
		return
	}
	copyOK := false
	if in, err := os.Open(self); err == nil {
		tmp := target + ".new"
		if out, err := os.OpenFile(tmp, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755); err == nil {
			_, cerr := io.Copy(out, in)
			_ = out.Close()
			if cerr == nil && os.Rename(tmp, target) == nil {
				copyOK = true
			} else {
				_ = os.Remove(tmp)
			}
		}
		_ = in.Close()
	}
	if !copyOK {
		applyLog("FAILED: cannot copy new exe, rolling back")
		_ = os.Rename(old, target)
		_ = exec.Command(target).Start()
		return
	}
	// 4) Launch the new binary (launcher mode opens daemon + desktop).
	launch := exec.Command(target)
	launch.Dir = filepath.Dir(target)
	if err := launch.Start(); err != nil {
		applyLog("FAILED: cannot launch new exe: %v, rolling back", err)
		_ = os.Remove(target)
		_ = os.Rename(old, target)
		_ = exec.Command(target).Start()
		return
	}
	// 5) Health check: a daemon reporting OUR version must come up.
	for i := 0; i < 50; i++ {
		if newDaemonHealthy() {
			applyLog("OK: new daemon v%s is up", AppVersion)
			_ = os.Remove(old)
			_ = os.Remove(filepath.Join(updateDir(), "pkg.zip"))
			return
		}
		time.Sleep(500 * time.Millisecond)
	}
	applyLog("FAILED: new daemon never became healthy, rolling back")
	_ = os.Remove(target)
	_ = os.Rename(old, target)
	rb := exec.Command(target)
	rb.Dir = filepath.Dir(target)
	_ = rb.Start()
}
